// Phase 26.26 — normalize definitions for transport (id-free, JSON-safe).
//
// Import and export both normalize a definition into a clean, portable shape: JSON-safe (no
// functions / undefined / class instances) and with all component/runtime ids stripped from the
// tree — component ids are regenerated by the server on apply, so carrying them across sites would
// only risk collisions. The template's OWN id (its namespace identity) and all portable data
// (responsive values, tokens, style bindings, state styles, asset URLs) are preserved verbatim.

import { isTemplateTreeLayout, type TemplateDefinition } from '../contracts'
import type { PatternTree, PatternSectionSnapshot, PatternBlockSnapshot } from '../../patterns/library'

/** Deep JSON clone — drops functions/undefined, guarantees a serializable value. */
export function jsonClone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T
}

function stripBlockIds(block: PatternBlockSnapshot): PatternBlockSnapshot {
  const { id: _id, ...rest } = block as PatternBlockSnapshot & { id?: string }
  const data = rest.data && typeof rest.data === 'object' ? { ...(rest.data as Record<string, unknown>) } : rest.data
  if (data && Array.isArray((data as Record<string, unknown>).blocks)) {
    ;(data as Record<string, unknown>).blocks = ((data as Record<string, unknown>).blocks as PatternBlockSnapshot[]).map(
      stripBlockIds,
    )
  }
  return { ...rest, data }
}

function stripSectionIds(section: PatternSectionSnapshot): PatternSectionSnapshot {
  const { id: _id, ...rest } = section as PatternSectionSnapshot & { id?: string }
  return { ...rest, blocks: (rest.blocks ?? []).map(stripBlockIds) }
}

/** Return a copy of the tree with every section/block id removed. */
export function stripTreeIds(tree: PatternTree): PatternTree {
  return { ...tree, sections: (tree.sections ?? []).map(stripSectionIds) }
}

/** Produce a portable, id-free, JSON-safe copy of a definition (for export or after import). */
export function normalizeDefinition(def: TemplateDefinition): TemplateDefinition {
  const cloned = jsonClone(def)
  if (isTemplateTreeLayout(cloned.layout)) {
    cloned.layout = { kind: 'tree', tree: stripTreeIds(cloned.layout.tree) }
  }
  return cloned
}
